const pxOnline=initial.backend===true||['http:','https:'].includes(location.protocol);
const px={readStates:{},user:null,loaded:false,content:{},posts:[],mine:[],friends:[],inbox:[],messages:[],devices:[],providers:[],requests:[],tab:'discover',busy:false,aiReady:false,aiError:'',draft:{},traitIndex:0,deviceMap:'body',bellMuted:stored.support?.preferences?.bellMuted||false};
const pxText=(zh,en)=>t(en,zh);
const pxApi=async(path,body,method,options={})=>{const token=psToken(),identity=/^(public$|auth\/)/.test(path);if(!identity&&!token.scope)throw new Error(psSaveError());if(!pxOnline)throw new Error(pxText('当前离线，请通过本地服务打开以连接账号和后台。','Open the local service to connect your account.'));const timeout=options.timeout??((method|| (body?'POST':'GET'))==='GET'?12000:0),controller=timeout?new AbortController():null,timer=controller?setTimeout(()=>controller.abort(),timeout):null;try{const r=await fetch('/api/'+path,{method:method||(body?'POST':'GET'),headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,credentials:'same-origin',signal:controller?.signal});let d;try{d=await r.json();}catch{throw new Error(pxText('服务暂时不可用，请稍后重试。','Service unavailable. Please retry.'));}if(!identity&&!psCurrent(token))throw Object.assign(new Error('Account changed'),{code:'SCOPE_CHANGED'});if(!r.ok){const error=new Error(ewI18n.error(d.error||'Request failed',state.lang));error.status=r.status;throw error;}return d;}catch(error){if(!identity&&!psCurrent(token))throw Object.assign(new Error('Account changed'),{code:'SCOPE_CHANGED'});throw error;}finally{if(timer)clearTimeout(timer);}};
async function pxSaveRecord(record){const token=psToken();if(!pxOnline||!token.scope)return false;try{await pxApi('records',record);if(psCurrent(token))toast(psText('Saved on this device and recorded by the server','已保存在本机，后台已记录','已儲存在本機，後台已記錄','འཕྲུལ་ཆས་འདི་དང་རྒྱབ་ལྗོངས་གཉིས་ཀར་ཉར་ཟིན།'));return true;}catch(error){if(psCurrent(token)&&error.code!=='SCOPE_CHANGED')toast(psText('Saved on this device; this server write failed.','已保存在本机，本次未写入后台。','已儲存在本機，本次未寫入後台。','འཕྲུལ་ཆས་འདིར་ཉར་ཟིན། ཐེངས་འདིར་རྒྱབ་ལྗོངས་སུ་ཉར་མ་ཐུབ།'));return false;}}
function ewMainHeader(title,kicker,tools='',extra=''){return `<header class="ew-main-header ${extra}"><div><span class="ew-page-eyebrow">${kicker}</span><h1>${title}</h1></div><div class="ew-header-tools">${tools}</div></header>`;}
function pxTop(title,sub='',back='home',right=''){return `<header class="px-top"><button class="icon-btn flat" data-action="go" data-to="${back}" aria-label="${pxText('返回','Back')}">${icon('back')}</button><div style="flex:1"><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${right||`<button class="icon-btn flat" data-action="ambient" aria-label="${pxText('外观','Appearance')}">${icon(isNight()?'moon':'sun')}</button>`}</header>`;}
function pxTile(symbol,name,description,to){return `<button class="px-tile" data-action="go" data-to="${to}"><span class="px-tile-art" aria-hidden="true"><i></i><i></i></span>${icon(symbol)}${icon('arrow','icon px-arrow')}<b>${name}</b><small>${description}</small></button>`;}
function pxDeviceRow(map){return `<div class="px-mini-row">${icon('activity')}<div><b>${pxText('设备与健康数据','Devices & health data')}</b><p>${pxText('检测设备 · 运动手环','Measurements · Wearables')}</p></div><button data-action="px-devices" data-map="${map}">${pxText('查看','View')}</button></div>`;}
Object.assign(paths,{activity:'M3 12h4l3-8 4 16 3-8h4','volume-off':'M11 4 6 8H2v8h4l5 4ZM16 8l6 8m0-8-6 8',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',video:'M3 5h12v14H3Zm12 5 6-4v12l-6-4',logout:'M9 4H3v16h6m4-4 5-4-5-4m-5 4h13'});
function pxHome(){return `<section class="page home home-v4"><header class="home-v4-header"><div class="ew-brand"><span class="ew-brand-mark" aria-hidden="true"><i></i><i></i></span><div><h1>${pxText('东方智慧','Eastern Wisdom')}</h1><p>${pxText('让智慧，成为日常的陪伴','WISDOM FOR EVERYDAY LIFE')}</p></div></div><div class="home-header-actions"><button class="icon-btn flat" data-action="entry-notices" aria-label="${pxText('通知','Notifications')}">${icon('bell')}</button><button class="icon-btn flat" data-action="entry-messages" aria-label="${pxText('消息','Messages')}">${icon('mail')}</button></div></header>${dailyBanner()}<div class="home-section-heading"><h2>${pxText('三大地图，一段成长旅程','Three paths. Your journey.')}</h2>${link(pxText('全部','Explore'),'gate')}</div>${homepageMaps()}${dailyDrawEntry()}${shortcutRow()}</section>`;}
function pxMapPage(kind){const info={life:[pxText('生命地图','Life map'),pxText('认识自己','Know yourself'),'tree','KNOW YOURSELF'],body:[pxText('身体地图','Body map'),pxText('修复自己','Restore yourself'),'leaf','RESTORE YOURSELF'],mind:[pxText('心智地图','Mind map'),pxText('提升自己','Grow yourself'),'lotus','GROW YOURSELF']}[kind];let tiles;
 const config=(px.content.maps||[]).find(x=>x.id===kind);if(config){info[0]=esc(ewI18n.field(config,'name',state.lang));info[1]=esc(ewI18n.field(config,'heroTitle',state.lang));}
 if(kind==='life')tiles=[['spark',pxText('天赋特质','Strengths'),pxText('发现你的优势','Notice your strengths'),'traits'],['compass',pxText('人生课题','Life themes'),pxText('选择在意的方向','Choose your direction'),'lifeThemes'],['chart',pxText('紫微命盘','Zi Wei chart'),pxText('探索传统文化','Explore cultural symbols'),'ziweiChart'],['book',pxText('文化与记录','Culture & notes'),pxText('了解 · 觉察 · 回看','Learn · Reflect · Review'),'ziweiCulture']];
 if(kind==='body')tiles=[['activity',pxText('身心自评','Body check-in'),pxText('四个问题，了解此刻','Four quick observations'),'bodyAssessment'],['leaf',pxText('中医导引','Daoyin'),pxText('温和活动，舒展身心','Gentle movement'),'bodyCulture'],['moon',pxText('睡眠与压力','Sleep & stress'),pxText('找到适合的放松练习','Choose a calming practice'),'bodyRecovery'],['headphones',pxText('放松音景','Soundscapes'),pxText('让声音陪你片刻','A moment in sound'),'music']];
 if(kind==='mind')tiles=[['lotus',pxText('禅修静心','Meditation'),pxText('从一次呼吸开始','Begin with one breath'),'zenPractice'],['heart',pxText('情绪觉察','Emotions'),pxText('记下此刻的感受','Notice how you feel'),'emotionAwareness'],['book',pxText('修习课程','Learning'),pxText('把智慧带进日常','Bring learning into life'),'buddhistCourses'],['clock',pxText('每日安排','Daily rhythm'),pxText('留一点时间给自己','Make a little space'),'timeline']];
 const bodyEntry=state.wellness.body[today()],mindEntry=state.wellness.mind[today()];const summary=kind==='body'&&bodyEntry?body4Fields().map(([key,name])=>name+' · '+answerLabel(key,bodyEntry[key])).join(' / '):kind==='mind'&&mindEntry?moodName(mindEntry.mood):kind==='life'&&state.daily.traits?pxText('已保存特质观察','Strengths saved'):'';
 return `<section class="page px-map-page" data-map="${kind}">${pxTop(info[0])}<div class="px-map-hero ew-map-intro"><span class="ew-map-scene" aria-hidden="true"></span><span class="px-kicker">${info[3]}</span><h2>${info[1]}</h2><p>${pxText('从此刻需要的方向开始','Start with what you need today')}</p><span class="px-orbit" aria-hidden="true">${icon(info[2],'icon-lg')}</span></div><div class="px-grid">${tiles.map(x=>pxTile(...x)).join('')}</div><div class="ew-map-flow" aria-label="${pxText('觉察、实践与回看','Reflect, practice and revisit')}">${[[pxText('觉察当下','Reflect'),{life:'traits',body:'bodyAssessment',mind:'emotionAwareness'}[kind]],[pxText('开始实践','Practice'),{life:'lifeThemes',body:'bodyRecovery',mind:'zenPractice'}[kind]],[pxText('回看记录','Revisit'),{life:'lifeReview',body:'bodyHistory',mind:'mindHistory'}[kind]]].map(([label,to],i)=>`<button data-action="go" data-to="${to}"><span>0${i+1}</span>${label}${icon('arrow')}</button>`).join('')}</div>${summary?`<p class="px-note px-status-dot">${esc(summary)}</p>`:''}${pxDeviceRow(kind)}<div class="px-chips">${go(pxText('成长记录','Growth records'),'growth','link')}${kind==='life'?go(pxText('生活记录','Life notes'),'lifeReview','link'):''}</div></section>`;
}
function pxGate(){return `<section class="page">${pxTop(pxText('三大地图','Three maps'))}<div class="px-grid">${pxTile('tree',pxText('认识自己','Know yourself'),pxText('天赋 · 课题 · 紫微','Strengths · Themes · Zi Wei'),'lifeResult')}${pxTile('leaf',pxText('修复自己','Restore yourself'),pxText('自评 · 睡眠 · 导引','Check-in · Rest · Daoyin'),'body')}${pxTile('lotus',pxText('提升自己','Grow yourself'),pxText('禅修 · 情绪 · 课程','Meditation · Emotions · Learning'),'mind')}${pxTile('chart',pxText('成长记录','Growth records'),pxText('回看你的日常','Review your everyday practice'),'growth')}</div></section>`;}
function pxAssessment(){return `<section class="page">${pxTop(pxText('身心自评','Body check-in'),pxText('选择最接近此刻的感受','Choose how you feel now'),'body')}<form id="px-body-form" class="px-quick-form">${body4Fields().map(([key,label])=>`<label>${label}<select class="input" name="${key}" required><option value="">${pxText('请选择','Choose')}</option>${answerChoices()[key].map(([v,n])=>`<option value="${v}" ${state.wellness.body[today()]?.[key]===v?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<button class="btn" type="submit">${pxText('保存此刻','Save check-in')}</button></form>${body4Entry()?`<div class="px-mini-row"><div><b>${body4Evaluation(body4Entry()).title}</b><p>${body4Evaluation(body4Entry()).copy}</p></div></div>${button(pxText('放松一分钟','One-minute breathing'),'start-practice','data-practice="breath"','full')}`:''}<p class="px-note">${pxText('自评记录，用于日常觉察。','A personal check-in for everyday awareness.')}</p>${pxDeviceRow('body')}</section>`;}
function pxTraits(){const index=Math.min(px.traitIndex,lifeTraits.length-1),item=lifeTraits[index];return `<section class="page">${pxTop(pxText('天赋特质','Strengths'),`${index+1} / ${lifeTraits.length}`,'lifeResult')}<article class="card"><span class="px-kicker">${pxText('观察自己','SELF OBSERVATION')}</span><h2 style="margin:15px 0">${ewI18n.content(item,"",state.lang)}</h2><p>${ewI18n.content(item,"q",state.lang)}</p><div class="choice-list mt24">${traitOptions().map(([value,label])=>`<button class="option" data-action="life4-trait-pick" data-trait="${item.id}" data-value="${value}" aria-pressed="${String(state.traitDraft[item.id])===value}">${label}${state.traitDraft[item.id]===value?icon('check'):''}</button>`).join('')}</div></article><div class="row mt16"><button class="btn secondary" data-action="px-trait-step" data-step="-1" ${index===0?'disabled':''}>${pxText('上一题','Previous')}</button>${index===lifeTraits.length-1?button(pxText('保存观察','Save'),'life4-trait-save','',''):button(pxText('下一题','Next'),'px-trait-step','data-step="1"','')}</div><p id="life4-trait-error" class="error" role="alert"></p>${state.daily.traits?`<p class="px-note">${pxText('已有记录保留，完成后更新。','Your saved observations remain until you save again.')}</p>`:''}</section>`;}
let pxWheelFrame=0,pxWheelStart=0,pxWheelOffset=0,pxWheelPaint=-1;
function pxCardPool(){return px.loaded?(px.content.cards||[]).filter(c=>c.id&&c.zh):dailyCards;}
function pxCardPage(){const date=state.cardDate||today(),draw=state.daily.draws[date],card=draw&&(draw.snapshot||dailyCards.find(c=>c.id===draw.cardId));if(card)return `<section class="page">${pxTop(pxText('今日卡片','Daily card'),dateLabel(date))}<article class="px-card-result px-fade"><small>${pxText('留一份启发给今天','A THOUGHT FOR TODAY')}</small>${card.coverUrl?`<img class="px-card-cover" src="${esc(card.coverUrl)}" alt="">`:icon(card.symbol||'spark')}<h2>${esc(ewI18n.content(card,"",state.lang))}</h2><p>${esc(t(card.lineEn||card.lineZh,card.lineZh||''))}</p></article><div class="daily-card-actions">${favoriteButton('card',card.id)}<span class="small">${pxText('今日已定格 · 随时回看','Saved for today · Revisit anytime')}</span></div><div class="px-reading"><strong>${pxText('卡片启发','REFLECTION')}</strong><p>${esc(t(card.readingEn||card.readingZh,card.readingZh||''))}</p><p><b>${pxText('今天可以试试：','Try today: ')}</b>${esc(t(card.actionEn||card.actionZh,card.actionZh||''))}</p></div>${button(pxText('聊聊这张卡','Explore with AI'),'px-card-ai',`data-card="${esc(card.id)}"`,'full')}<p class="px-note">${pxText('卡片用于日常觉察。','A reflection prompt for everyday life.')}</p></section>`;
 const pool=pxCardPool();return `<section class="page">${pxTop(pxText('每日抽卡','Daily card'),pxText('轻触中心，定格此刻','Tap the centre to choose this moment'))}${pool.length?`<div class="px-wheel" id="px-wheel" aria-label="${pxText('自动滚动的卡片','Automatically rolling cards')}"><div class="px-wheel-strip" id="px-wheel-strip" aria-hidden="true"></div><button class="px-wheel-stop" data-action="px-wheel-stop" aria-label="${pxText('点击中心图片定格卡片','Stop on the centre card')}"></button></div><p class="px-wheel-help">${pxText('卡片正在流动 · 由你决定停下的瞬间','Rolling cards · You choose when to stop')}</p>`:`<div class="empty-state"><h3>${pxText('卡片准备中','Cards are being prepared')}</h3></div>`}</section>`;
}
function pxWheelLoop(){cancelAnimationFrame(pxWheelFrame);const strip=document.getElementById('px-wheel-strip');if(!strip)return;const pool=pxCardPool();if(!pool.length)return;pxWheelStart=performance.now();pxWheelOffset=crypto.getRandomValues(new Uint32Array(1))[0]%pool.length;pxWheelPaint=-1;const tick=now=>{if(!strip.isConnected)return;const position=(now-pxWheelStart)/230,whole=Math.floor(position),fraction=position-whole,base=(pxWheelOffset+whole)%pool.length;if(base!==pxWheelPaint){strip.innerHTML=Array.from({length:5},(_,i)=>{const c=pool[(base+i-2+pool.length*2)%pool.length];return `<div class="px-wheel-card"><div>${c.coverUrl?`<img src="${esc(c.coverUrl)}" alt="">`:icon(c.symbol||'spark')}<b>${esc(ewI18n.content(c,"",state.lang))}</b></div></div>`;}).join('');pxWheelPaint=base;}strip.style.transform=`translateY(${-fraction*148}px)`;strip.dataset.currentIndex=String((base+(fraction>=.5?1:0))%pool.length);pxWheelFrame=requestAnimationFrame(tick);};pxWheelFrame=requestAnimationFrame(tick);}
function pxChooseCard(){const el=document.getElementById('px-wheel-strip');if(!el||state.daily.draws[today()])return;const card=pxCardPool()[Number(el.dataset.currentIndex||0)];if(!card)return;cancelAnimationFrame(pxWheelFrame);const draw={cardId:card.id,date:today(),drawnAt:new Date().toISOString(),snapshot:JSON.parse(JSON.stringify(card)),selection:'centre-tap'};state.daily.draws[today()]=draw;state.cardDate=today();if(!dailyCards.some(x=>x.id===card.id))dailyCards.push(card);if(!persist()){delete state.daily.draws[today()];return;}render(false);pxSaveRecord({kind:'card',date:today(),data:draw});}
let pxBellContext;
function pxRingBell(){if(px.bellMuted)return;try{const cfg=(px.content.signin||[])[0];if(cfg?.audioUrl){const a=new Audio(cfg.audioUrl);a.volume=.55;a.play().catch(()=>toast(pxText('签到已记录，声音暂时无法播放。','Checked in; sound is unavailable.')));return;}const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return;pxBellContext=pxBellContext||new Context();pxBellContext.resume();const start=pxBellContext.currentTime;[174.61,350.3,469.6,700.7,940.2].forEach((f,i)=>{const o=pxBellContext.createOscillator(),g=pxBellContext.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(.18/(i+1),start+.015);g.gain.exponentialRampToValueAtTime(.0001,start+2.5-i*.15);o.connect(g).connect(pxBellContext.destination);o.start(start);o.stop(start+3);});}catch{}}
function pxCheckin(){const done=!!state.daily.checkins[today()],count=Object.keys(state.daily.checkins).length;return `<section class="page">${pxTop(pxText('每日签到','Daily check-in'),dateLabel(today()))}<div class="px-bell-area"><span class="px-kicker">${t("A MOMENT FOR YOURSELF","留给自己的片刻")}</span><button class="px-bell" data-action="px-bell" aria-label="${done?pxText('再次听钟声','Listen to the bell'):pxText('敲钟签到','Ring to check in')}">${icon('bell')}</button><h2>${done?pxText('今日，已留下一声回响','A moment kept for today'):pxText('轻敲一下，回到此刻','Ring once. Return to this moment.')}</h2><p>${done?pxText('再次轻敲，可以重听钟声','Tap again to hear the bell'):pxText('用一声钟鸣，开启今天','Begin your day with a gentle bell')}</p><button class="px-sound-toggle" data-action="px-bell-mute">${icon(px.bellMuted?'volume-off':'volume')}${px.bellMuted?pxText('声音已关闭','Sound off'):pxText('钟声已开启','Sound on')}</button></div><div class="row"><h3 style="font-size:14px">${pxText('最近七天','Past seven days')}</h3><small>${count} ${pxText('天已记录','days recorded')}</small></div><div class="daily-week-grid">${weekDates().map(d=>`<div class="daily-week-day ${state.daily.checkins[d]?'checked':''}"><small>${ewFormatDate(new Date(d+'T12:00:00'),{weekday:'short'})}</small><b>${Number(d.slice(-2))}</b><span>${state.daily.checkins[d]?icon('check'):'·'}</span></div>`).join('')}</div></section>`;}
function pxSign(){pxRingBell();const first=!state.daily.checkins[today()];if(first){if(!psCommit(()=>{state.daily.checkins[today()]={at:new Date().toISOString()};state.checkedIn=true;}))return;pxSaveRecord({kind:'checkin',date:today(),data:state.daily.checkins[today()]});}render(false);document.querySelector('.px-bell')?.classList.add('ringing');if(first)toast(psText('Today’s check-in saved on this device','今日签到已保存在本机','今日簽到已儲存在本機','དེ་རིང་གི་ཐོ་འགོད་འཕྲུལ་ཆས་འདིར་ཉར་ཟིན།'));}
function pxMusic(){const tracks=px.loaded?(px.content.music||[]):musicTracks;return `<section class="page">${pxTop(pxText('冥想音乐','Soundscapes'),pxText('选择一段声音，留一点空间','Choose a sound. Make a little space.'))}<div class="px-media-list">${tracks.map(track=>`<article class="px-media-item"><span class="px-media-icon" aria-hidden="true"><span class="px-audio-bars"><i></i><i></i><i></i><i></i><i></i></span></span><div class="px-media-copy"><h3>${esc(t(track.en||track.zh,track.zh||track.title||''))}</h3><p>${esc(t(track.descEn||track.descZh||'',track.descZh||''))}</p></div><button class="icon-btn" data-action="music-play" data-track="${track.id}" aria-label="${pxText('播放','Play')+esc(track.zh||'')}">${icon('play')}</button></article>`).join('')}</div>${tracks.length?'':`<div class="empty-state"><h3>${pxText('音景准备中','Soundscapes are being prepared')}</h3></div>`}<p class="px-note">${pxText('选择声音后，可调整音量与聆听时长。','Choose a sound, then adjust volume and listening duration.')}</p></section>`;}

function pxChat(){return `<section class="page ss-page px-ai-page ew-ai-page ew-ai-simple">${ewMainHeader(pxText('AI对话','AI chat'),'',`<button class="icon-btn flat" data-action="ss-ai-clear" aria-label="${pxText('清空对话','Clear conversation')}">${icon('refresh')}</button>`,'ss-chat-header')}<p class="ew-ai-hint">${pxText('这是你的AI对话空间，可以聊聊情绪、日常练习或东方智慧。','Your AI conversation space for feelings, everyday practice, and Eastern wisdom.')}</p><div class="ew-ai-connection"><span class="${px.aiReady?'is-ready':''}"></span>${px.aiReady?pxText('AI已连接','AI connected'):pxText('AI尚未连接','AI connection not configured')}</div>${state.ssAiContext?`<div class="ss-chat-scope"><span>${esc(state.ssAiContext.title)}</span><button data-action="ss-context-clear">${pxText('移除','Remove')}</button></div>`:''}<div class="ss-chat-area" id="px-ai-messages" aria-live="polite">${state.support.ai.map(m=>`<article class="ss-message ${m.role==='user'?'ss-user':''}"><div class="ss-message-label">${m.role==='user'?pxText('我','Me'):pxText('AI','AI')}</div><div class="ss-bubble">${esc(m.text)}</div></article>`).join('')}${px.busy?`<p class="px-note" role="status">${pxText('正在思考…','Thinking…')}</p>`:''}</div><div class="px-chips ew-ai-followups">${px.aiError?`<button data-action="px-ai-retry">${pxText('重试','Retry')}</button>`:''}</div><p class="ss-error" role="alert">${esc(px.aiError)}</p><form id="ss-ai-form" class="ss-chat-compose"><label class="sr-only" for="ss-ai-input">${pxText('输入问题','Your question')}</label><textarea class="input" id="ss-ai-input" rows="2" maxlength="2000" placeholder="${pxText('例如：最近很难静下心来…','For example: I find it hard to settle my mind…')}" ${px.busy?'disabled':''} required></textarea><button class="btn" type="submit" ${px.busy?'disabled':''}>${pxText('发送','Send')}</button></form><p class="ew-compose-note">${pxText('AI内容仅供参考 · 对话不会自动公开到社群','AI responses are for reference · Conversations are not automatically shared')}</p></section>`;}

async function pxAsk(text,retry=false){if(px.busy||!text?.trim()||!personalStorage.scope)return;const token=psToken(),before=psClone(state.support.ai);px.busy=true;px.aiError='';if(!retry)state.support.ai.push({id:ssId(),role:'user',text:text.trim(),at:new Date().toISOString()});state.support.ai=state.support.ai.slice(-40);if(!persist()){state.support.ai=before;px.busy=false;return;}state.page='serviceChat';render(false);pxScrollChat();try{const d=await pxApi('ai/chat',{messages:state.support.ai.slice(-12).map(m=>({role:m.role,content:m.text})),context:state.ssAiContext?{title:state.ssAiContext.title,summary:state.ssAiContext.summary}:null});state.support.ai.push({id:ssId(),role:'assistant',text:d.text,at:new Date().toISOString()});if(!persist())px.aiError=psSaveError();}catch(e){if(psCurrent(token))px.aiError=e.message;}finally{if(!psCurrent(token))return;px.busy=false;if(['service','serviceChat'].includes(state.page)){render(false);pxScrollChat();}}}
function pxScrollChat(){requestAnimationFrame(()=>{const area=document.getElementById('px-ai-messages');if(area)area.scrollTop=area.scrollHeight;});}
ssAsk=(text)=>pxAsk(text);
ssInterpret=id=>{const r=ssReportById(id);if(!r?.ready)return;state.ssAiContext={title:r.title,summary:r.summary};pxAsk(pxText('请帮我理解这份记录：','Please explain this record: ')+r.title+'\n'+r.rows.map(([a,b])=>a+'：'+b).join('\n'));};
function pxAccount(){return `<section class="page">${pxTop(pxText('账号','Account'),'','profile')}${px.user?`<article class="card"><h2>${esc(px.user.name)}</h2><p>@${esc(px.user.username)} · ${esc({admin:'管理员',operator:'运营',reviewer:'审核员',teacher:'老师',user:'学员'}[px.user.role]||px.user.role)}</p><button class="btn secondary full mt16" data-action="px-logout">${pxText('退出账号','Sign out')}</button></article>`:`<form id="px-account-form" class="px-account-form"><label>${pxText('账号','Username')}<input class="input" name="username" autocomplete="username" pattern="[A-Za-z0-9_]{3,32}" placeholder="${pxText('3–32位字母、数字或下划线','3–32 letters, numbers or underscores')}" required></label><label>${pxText('密码','Password')}<input class="input" name="password" type="password" autocomplete="current-password" minlength="1" maxlength="128" required></label><label>${pxText('昵称（注册时填写）','Name (for registration)')}<input class="input" name="name" maxlength="24"></label><button class="btn" name="mode" value="login">${pxText('登录','Sign in')}</button><button class="btn secondary" name="mode" value="register">${pxText('注册学员账号','Create an account')}</button><p class="error" id="px-account-error" role="alert"></p></form><p class="px-note">${pxText('账号用于发布内容、好友交流与设备数据。当前浏览器已有的个人记录继续保留。','Use your account for publishing, connections and devices. Existing local records stay here.')}</p>`}</section>`;}
function pxPostCard(p,mine=false){return `<article class="px-post"><header>${ssAvatar(p.authorName||'')}<div><b>${esc(p.authorName||'')}${p.authorRole==='teacher'?' · '+pxText('老师','Teacher'):''}</b><small>${esc(ewFormatDate(new Date(p.createdAt),{year:'numeric',month:'numeric',day:'numeric'}))}</small></div>${mine?`<span class="badge">${esc({pending:t('In review','待审核'),published:t('Published','已发布'),rejected:t('Not approved','未通过'),withdrawn:t('Withdrawn','已撤回'),draft:t('Draft','草稿')}[p.status]||p.status)}</span>`:''}</header>${p.mediaUrl?`<video controls playsinline preload="metadata" src="${esc(p.mediaUrl)}"></video>`:''}<h3>${esc(p.title)}</h3><p>${esc(p.body||'')}</p><footer>${mine&&p.reason?`<span>${pxText('审核说明：','Review note: ')+esc(p.reason)}</span>`:''}${mine?`<button data-action="px-edit-post" data-id="${p.id}">${pxText('编辑','Edit')}</button>${['pending','published'].includes(p.status)?`<button data-action="px-withdraw" data-id="${p.id}">${pxText('撤回','Withdraw')}</button>`:''}`:''}</footer></article>`;}
function communityPreviewVideo(){return `<article class="px-post community-preview-video"><header><span class="badge">${pxText('视频预览','Video preview')}</span><small>${pxText('你提供的短视频','Your supplied clip')}</small></header><video controls playsinline preload="metadata" src="${COMMUNITY_PREVIEW_VIDEO}" aria-label="${pxText('社群短视频预览','Community video preview')}"></video><h3>${pxText('社群短视频展示','A clip in the community')}</h3><p>${pxText('体验视频播放与社群展示效果。','Preview video playback and the community layout.')}</p></article>`;}
function pxCommunity(){return communityFeedPage();}
function pxPublish(){const d=px.draft;return `<section class="page">${pxTop(pxText('发布内容','Create a post'),pxText('提交审核后公开展示','Public after review'),'communityPosts')}<form id="px-publish-form" class="px-account-form"><label>${pxText('标题','Title')}<input name="title" class="input" maxlength="80" value="${esc(d.title||'')}" required></label><label>${pxText('内容','Content')}<textarea name="body" class="input" rows="4" maxlength="4000" required>${esc(d.body||'')}</textarea></label><label>${pxText('视频切片或教学视频','Video clip or teaching video')}<input name="media" type="file" accept="video/mp4,video/webm,video/quicktime" class="input"></label>${d.mediaUrl?`<p class="px-note">${pxText('已有视频，上传新文件可替换。','Video attached. Upload a file to replace it.')}</p>`:''}<button class="btn" type="submit" name="mode" value="pending">${pxText('提交审核','Submit for review')}</button><button class="btn secondary" type="submit" name="mode" value="draft">${pxText('保存草稿','Save draft')}</button><p class="error" id="px-publish-error" role="alert"></p><p class="px-note">${pxText('视频上限50MB，支持MP4、WebM和MOV。','Up to 50 MB. MP4, WebM or MOV.')}</p></form></section>`;}
async function pxLoadFeed(){return pxReadRun('feed',async()=>({posts:(await pxApi('community/posts')).items,mine:px.user?(await pxApi('community/mine')).items:[]}),d=>{const changed=JSON.stringify(d.posts)!==JSON.stringify(px.posts)||JSON.stringify(d.mine)!==JSON.stringify(px.mine);px.posts=d.posts;px.mine=d.mine;return changed;});}
function pxFriends(){return `<section class="page">${communityHeader('friends')}${px.user?`<form id="px-friend-form" class="row"><input name="username" class="input" placeholder="${pxText('输入学员账号','Enter a username')}" required><button class="btn" type="submit">${pxText('添加','Add')}</button></form><p class="px-note">${pxText('发送申请，对方同意后成为好友。','Send a request. Connect after it is accepted.')}</p>${px.friends.map(f=>`<div class="px-mini-row">${ssAvatar(f.name)}<div><b>${esc(f.name)}</b><p>@${esc(f.username)} · ${esc(f.status==='accepted'?pxText('已连接','Connected'):f.incoming?pxText('请求添加你','Wants to connect'):pxText('等待同意','Request sent'))}</p></div>${f.status==='accepted'?`<button data-action="px-conversation" data-id="${f.id}">${pxText('对话','Chat')}</button>`:f.incoming?`<button data-action="px-accept-friend" data-id="${f.id}">${pxText('同意','Accept')}</button>`:''}<button data-action="px-remove-friend" data-id="${f.id}">${pxText('移除','Remove')}</button></div>`).join('')}`:go(pxText('登录账号','Sign in'),'account','full')}</section>`;}
function pxInbox(){return `<section class="page">${communityHeader('communityInbox')}${px.inbox.length?px.inbox.map(c=>`<button class="ss-row" data-action="px-conversation" data-id="${c.id}">${ssAvatar(c.name)}<span><b>${esc(c.name)}</b><small>${esc(c.lastMessage||'')}</small></span>${icon('arrow')}</button>`).join(''):`<div class="empty-state"><h3>${pxText('暂无对话','No conversations yet')}</h3></div>`}${go(pxText('查看我的好友','View friends'),'friends','secondary full')}</section>`;}
function pxConversation(){const f=px.friends.find(x=>x.id===px.chatId);return `<section class="page">${pxTop(esc(f?.name||pxText('对话','Conversation')),'','communityInbox')}<div class="ss-chat-area" id="px-social-messages">${px.messages.map(m=>`<article class="ss-message ${m.senderId===px.user?.id?'ss-user':''}"><div class="ss-bubble">${esc(m.body)}</div></article>`).join('')}</div><form id="px-message-form" class="row mt16"><input name="body" class="input" maxlength="2000" placeholder="${pxText('写一条消息','Write a message')}" required><button class="btn" type="submit">${pxText('发送','Send')}</button></form></section>`;}
function pxTeachers(){const items=px.content.teachers||[];return `<section class="page">${pxTop(pxText('老师一对一','Teacher support'),'','community')}${items.length?items.map(x=>`<article class="card mb16"><h3>${esc(academyTeacherName(x))} ${academyTeacherBadge(x)}</h3><p>${esc(ewI18n.field(x,'bio',state.lang)||x.body||'')}</p><p class="px-note">${esc(ewI18n.field(x,'specialty',state.lang))}</p>${x.profileType==='demo'?`<button class="btn full" data-action="at-open" data-id="${esc(x.id)}">${t('View courses','查看课程')}</button>`:`<button class="btn full" data-action="px-service-request" data-id="${esc(x.id)}">${pxText('提出交流需求','Request a conversation')}</button>`}</article>`).join(''):`<div class="empty-state"><h3>${pxText('老师资料准备中','Teachers are being prepared')}</h3><p>${pxText('开放服务后，可在这里了解老师并提出需求。','Meet teachers and request support when available.')}</p></div>`}<h3 style="font-size:15px;margin:18px 0">${pxText('我的需求','My requests')}</h3>${px.requests.map(r=>`<div class="px-mini-row"><div><b>${esc(r.teacherName)}</b><p>${esc(r.body)} · ${esc({pending:t('Pending','待处理'),accepted:t('Accepted','已受理'),closed:t('Closed','已结束'),cancelled:t('Cancelled','已取消')}[r.status]||r.status)}</p></div>${r.status==='pending'?`<button data-action="px-cancel-request" data-id="${r.id}">${pxText('取消','Cancel')}</button>`:''}</div>`).join('')}</section>`;}
function pxDevices(){const items=px.devices.filter(x=>x.map===px.deviceMap),providers=px.providers.filter(p=>(p.maps||['life','body','mind']).includes(px.deviceMap));return `<section class="page">${pxTop(pxText('设备与健康数据','Devices & data'),pxText('数据需经你授权后接入','Connect data with your permission'),{life:'lifeResult',body:'body',mind:'mind'}[px.deviceMap])}<div class="ew-device-scope"><span class="px-kicker">${pxText('身心数据连接','BODY DATA CONNECTION')}</span><div class="ew-signal-trace" aria-hidden="true">${icon('activity')}<span>DEVICE / DATA</span></div><h2>${items.some(d=>d.measurements?.length)?pxText('已接收设备数据','Measurements received'):pxText('等待真实数据接入','Awaiting your data')}</h2><p>${pxText('仅展示你已授权设备提供的测量记录','Only measurements from devices you authorize')}</p></div>${items.map(d=>`<article class="card px-device mb16"><div class="row"><h3>${esc(d.name||d.provider)}</h3><small>${d.status==='connected'?pxText('已连接','Connected'):pxText('等待授权接入','Awaiting connection')}</small></div>${d.measurements?.length?`<dl>${d.measurements.slice(0,6).map(m=>`<div><dt>${esc(m.metric)}</dt><dd>${esc(m.value)} <small>${esc(m.unit||'')}</small></dd></div>`).join('')}</dl><p class="px-note">${pxText('测量时间：','Measured: ')+esc(d.measurements[0].measuredAt)}</p>`:`<p class="px-note">${pxText('尚未收到设备测量数据。','No measurements received yet.')}</p>`}<button class="btn secondary" data-action="px-device-unlink" data-id="${d.id}">${pxText('解除授权','Disconnect')}</button></article>`).join('')}${!px.user?go(pxText('登录后连接设备','Sign in to connect'),'account','full'):providers.length?`<form id="px-device-form" class="px-account-form"><label>${pxText('设备服务','Provider')}<select class="input" name="provider">${providers.map(p=>`<option value="${esc(p.id)}">${esc(p.name||p.title||p.id)}</option>`).join('')}</select></label><label>${pxText('设备编号','Device ID')}<input class="input" name="deviceId" maxlength="100" required></label><label><input type="checkbox" name="consent" required> ${pxText('我同意连接此设备的数据','I consent to connect this device')}</label><button class="btn">${pxText('申请连接','Connect device')}</button></form>`:`<div class="empty-state">${icon('activity','icon-lg')}<h3>${pxText('设备服务准备中','Device connections are being prepared')}</h3><p>${pxText('检测设备与运动手环接口已预留，接入后在这里授权。','Authorize supported measurement devices and wearables here.')}</p></div>`}</section>`;}
async function pxLoadDevices(){if(!pxOnline)return;return pxReadRun('devices',()=>pxApi('devices'),d=>{px.devices=d.items;px.providers=d.providers;});}
async function pxLoadConnections(){if(!pxOnline||!px.user)return;return pxReadRun('connections',async()=>{const [friends,inbox,requests]=await Promise.all([pxApi('friends'),pxApi('messages'),pxApi('service-requests')]);return {friends:friends.items,inbox:inbox.items,requests:requests.items};},d=>Object.assign(px,d));}
async function pxOpenChat(id){px.chatId=id;return pxReadRun('chat',()=>pxApi('messages/'+encodeURIComponent(id)),d=>{if(px.chatId!==id)return;px.messages=d.items;navigate('conversation');requestAnimationFrame(()=>document.getElementById('px-message-form')?.scrollIntoView({block:'end'}));return false;});}
ssCompose=(to='feed',attachment=null)=>{px.draft={title:attachment?.title||'',body:attachment?attachment.title+'\n'+(attachment.subtitle||''):''};px.user?navigate('publish'):navigate('account');};
function pxPracticeButton(key){const p=practices[key];return `<button data-action="start-practice" data-practice="${key}">${icon(p.icon||'leaf')}<span><b>${practiceName(key)}</b><small>${minutes(p.seconds)}</small></span></button>`;}
function pxBodyCulture(){return `<section class="page">${pxTop(pxText('中医与导引','Daoyin'),'','body')}<p class="px-entry-note">${pxText('从温和的呼吸和身体觉察开始，按自己的舒适程度练习。','Begin with natural breathing and body awareness, at a comfortable pace.')}</p><div class="px-practice-choices">${['breath','scan','ground'].map(pxPracticeButton).join('')}</div><details><summary>${pxText('了解中医与导引文化','About Chinese traditions and daoyin')}</summary><p>${pxText('导引是东方传统中结合身体活动、呼吸与注意力的练习方式。这里提供日常觉察练习，可从短时体验开始。','Daoyin brings together movement, breathing and attention. Begin here with a short everyday awareness practice.')}</p><a href="https://www.nccih.nih.gov/health/qigong-what-you-need-to-know" target="_blank" rel="noopener">NCCIH · Qigong</a></details></section>`;}
function pxRecovery(){return `<section class="page">${pxTop(pxText('睡眠与压力','Sleep & stress'),'','body')}<div class="px-practice-choices">${['sleep','breath','scan'].map(pxPracticeButton).join('')}</div>${go(pxText('选择放松音景','Choose a soundscape'),'music','secondary full mt16')}</section>`;}
function pxZen(){return `<section class="page">${pxTop(pxText('禅修静心','Meditation'),pxText('选一段时间，安住此刻','Choose a little time to be here'),'mind')}<div class="px-map-hero"><span class="px-kicker">${t("RETURN TO THIS MOMENT","回到此刻")}</span><h2>${pxText('让注意力轻轻回来','Return gently')}</h2><p>${pxText('自然呼吸，按自己的节奏','Natural breathing, at your own pace')}</p><span class="px-orbit">${icon('lotus')}</span></div><div class="px-practice-choices">${['breath','zen','focus'].filter(k=>practices[k]).map(pxPracticeButton).join('')}</div></section>`;}
function pxLifeThemes(){const theme=lifeThemes.find(x=>x.id===px.lifeTheme)||lifeThemes[0],entry=px.lifeDraft||state.wellness.intentions[today()]||{};return `<section class="page">${pxTop(pxText('人生课题','Life themes'),'','lifeResult')}<div class="px-chips">${lifeThemes.map(x=>`<button data-action="px-life-theme" data-id="${x.id}" aria-pressed="${x.id===theme.id}">${ewI18n.content(x,"",state.lang)}</button>`).join('')}</div><p class="px-entry-note">${ewI18n.content(theme,"prompt",state.lang)}</p><form id="px-life-form" class="px-account-form"><label>${pxText('此刻的观察','What I notice')}<textarea name="intention" class="input" rows="3" maxlength="500" required>${esc(entry.intention||'')}</textarea></label><label>${pxText('愿意尝试的一小步','One small step')}<input name="direction" class="input" maxlength="500" value="${esc(entry.direction||'')}"></label><button class="btn">${pxText('保存觉察','Save reflection')}</button></form>${go(pxText('回看生活记录','Review life notes'),'lifeReview','link mt16')}</section>`;}
function pxEmotion(){const entry=px.emotionDraft||state.wellness.mind[today()]||{};return `<section class="page">${pxTop(pxText('情绪觉察','Emotional awareness'),'','mind')}<form id="px-emotion-form" class="px-account-form"><p class="px-note">${pxText('现在的你，更接近哪种感受？','Which feeling is closest to you now?')}</p><div class="px-emotion-options">${moodChoices().map(([value,label])=>`<button type="button" data-action="px-mood" data-value="${value}" aria-pressed="${entry.mood===value}">${label}</button>`).join('')}</div><input type="hidden" name="mood" value="${esc(entry.mood||'')}"><label>${pxText('想为自己记下什么？','What would you like to note?')}<textarea class="input" name="note" rows="3" maxlength="1000">${esc(entry.note||'')}</textarea></label><label>${pxText('此刻需要的一点照顾','What I need next')}<input class="input" name="next" maxlength="500" value="${esc(entry.next||'')}"></label><button class="btn">${pxText('保存此刻','Save this moment')}</button><p id="px-emotion-error" class="error" role="alert"></p></form>${go(pxText('回看情绪记录','Review emotional notes'),'mindHistory','link mt16')}</section>`;}
const pxNative={track:null,audio:null,elapsed:0,last:0,recorded:0,limit:600,volume:.36,error:''};
function pxNativeRecord(automatic=false){if(automatic&&personalStorage.blocked)return false;const seconds=Math.floor(pxNative.elapsed)-pxNative.recorded;if(seconds<1||!pxNative.track)return;state.daily.musicSessions.push({id:ssId(),date:today(),trackId:pxNative.track.id,seconds,endedAt:new Date().toISOString()});if(!persist()){state.daily.musicSessions.pop();return false;}pxNative.recorded+=seconds;return true;}
function pxNativeTick(){const a=pxNative.audio,now=performance.now();if(a&&!a.paused&&!a.seeking&&a.readyState>=2&&pxNative.last)pxNative.elapsed+=Math.max(0,(now-pxNative.last)/1000);pxNative.last=now;if(a&&!a.paused&&pxNative.limit&&pxNative.elapsed>=pxNative.limit){pxNative.elapsed=pxNative.limit;a.pause();pxNativeRecord(true);}const elapsed=document.getElementById('px-native-elapsed'),status=document.getElementById('px-native-status'),play=document.getElementById('px-native-toggle');if(elapsed)elapsed.textContent=musicClock(pxNative.elapsed);if(status)status.textContent=pxNative.error||(a?.paused?pxText('已暂停','Paused'):pxText('正在聆听','Listening'));if(play){play.innerHTML=icon(a?.paused?'play':'pause','icon-lg');play.setAttribute('aria-label',a?.paused?pxText('播放','Play'):pxText('暂停','Pause'));}}
function pxNativeStop(){if(!pxNative.audio)return true;pxNativeTick();pxNative.audio.pause();if(pxNativeRecord()===false){pxNative.error=psSaveError();return false;}pxNative.audio.remove();pxNative.audio=null;return true;}
function pxOpenNative(id,play=false){if(!personalStorage.scope){toast(psSaveError());return;}const track=(px.content.music||[]).find(x=>x.id===id)||musicTracks.find(x=>x.id===id);if(!track?.audioUrl)return;if(pxNativeStop()===false||!musicStop()){render(false);return;}stopAudio();Object.assign(pxNative,{track,elapsed:0,recorded:0,last:performance.now(),error:''});const token=psToken(),audio=new Audio(track.audioUrl);pxNative.audio=audio;audio.id='px-native-audio';audio.dataset.pxAudio=id;audio.preload='metadata';audio.loop=true;audio.volume=pxNative.volume;audio.hidden=true;document.body.append(audio);audio.addEventListener('play',()=>{if(psCurrent(token)&&pxNative.audio===audio){pxNative.last=performance.now();pxNativeTick();}});audio.addEventListener('pause',()=>{if(psCurrent(token)&&pxNative.audio===audio){pxNativeTick();pxNativeRecord(true);}});audio.addEventListener('error',()=>{if(psCurrent(token)&&pxNative.audio===audio){pxNative.error=pxText('音频暂时无法播放，请稍后重试。','Audio unavailable. Please retry.');pxNativeTick();}});navigate('externalMusic');if(play)audio.play().catch(()=>{if(!psCurrent(token)||pxNative.audio!==audio)return;pxNative.error=pxText('点击播放以开始聆听。','Tap play to start.');pxNativeTick();});}
function pxNativePage(){if(!pxNative.track)return pxMusic();const a=pxNative.audio,track=pxNative.track;return `<section class="page music-player">${pxTop(pxText('冥想音乐','Soundscape'),'','music')}<div class="music-player-title"><h1>${esc(ewI18n.content(track,"",state.lang))}</h1><p>${esc(t(track.descEn||track.descZh||'',track.descZh||''))}</p></div><div class="music-orbit music-art-waterside ${a&&!a.paused?'is-playing':''}"><span class="music-orbit-ring one"></span><span class="music-orbit-ring two"></span><span class="music-orbit-symbol">${icon('headphones','icon-lg')}</span></div><div class="row"><span id="px-native-elapsed">${musicClock(pxNative.elapsed)}</span>${favoriteButton('music',track.id)}</div><div class="music-controls"><button class="icon-btn" data-action="px-native-prev" aria-label="${pxText('上一首','Previous')}">${icon('back')}</button><button class="music-main-play" id="px-native-toggle" data-action="px-native-toggle" aria-label="${a?.paused?pxText('播放','Play'):pxText('暂停','Pause')}">${icon(a?.paused?'play':'pause','icon-lg')}</button><button class="icon-btn" data-action="px-native-next" aria-label="${pxText('下一首','Next')}">${icon('arrow')}</button></div><p id="px-native-status" class="music-play-status">${pxNative.error||(a?.paused?pxText('已暂停','Paused'):pxText('正在聆听','Listening'))}</p><label class="music-volume">${icon('volume')}<input id="px-native-volume" type="range" min="0" max="100" value="${Math.round(pxNative.volume*100)}" aria-label="${pxText('音量','Volume')}"></label><div class="music-timer-options">${[300,600,1200,0].map(seconds=>`<button data-action="px-native-limit" data-seconds="${seconds}" aria-pressed="${pxNative.limit===seconds}">${musicTimerName(seconds)}</button>`).join('')}</div><button class="btn secondary full mt16" data-action="go" data-to="music">${pxText('结束聆听','Finish listening')}</button></section>`;}
async function pxNativeAction(action,el){
 const token=psToken(),a=pxNative.audio;if(!a||!psCurrent(token))return;
 if(action==='px-native-toggle'){
  pxNative.error='';if(a.paused){try{await a.play();}catch{if(!psCurrent(token)||pxNative.audio!==a)return;pxNative.error=psText('Audio could not start. Tap play to retry.','音频暂未开始，请点击播放重试。','音訊暫未開始，請點擊播放重試。','སྒྲ་འགོ་འཛུགས་མ་ཐུབ། སླར་གཏོང་ལ་ནོན་རོགས།');pxNativeTick();return;}if(!psCurrent(token)||pxNative.audio!==a)return;}
  else{pxNativeTick();a.pause();pxNativeRecord();}pxNativeTick();
 }else if(action==='px-native-limit'){pxNative.limit=Number(el.dataset.seconds);render(false);}
 else if(action==='px-native-next'||action==='px-native-prev'){const tracks=px.loaded?px.content.music:musicTracks,index=tracks.findIndex(x=>x.id===pxNative.track.id),next=tracks[(index+(action==='px-native-next'?1:-1)+tracks.length)%tracks.length];if(next)musicPlay(next.id);}
}
